using System.Security.Claims;using MachineryManagerEnterprise.SharedKernel.Abstractions;using Microsoft.AspNetCore.Http;namespace MachineryManagerEnterprise.SharedKernel.Infrastructure;/// <summary>/// Provides the current user context from the ASP.NET Core HttpContext,/// implementing the <see cref="ICurrentUserService"/> abstraction./// </summary>public sealed class CurrentUserService : ICurrentUserService{    private readonly IHttpContextAccessor _httpContextAccessor;    /// <summary>    /// Initializes a new instance of the <see cref="CurrentUserService"/> class.    /// </summary>    /// <param name="httpContextAccessor">The HTTP context accessor.</param>    public CurrentUserService(IHttpContextAccessor httpContextAccessor)    {        _httpContextAccessor = httpContextAccessor;    }    /// <inheritdoc />    public Guid? UserId    {        get        {            var userIdClaim = _httpContextAccessor.HttpContext?.User?.FindFirstValue(ClaimTypes.NameIdentifier)                ?? _httpContextAccessor.HttpContext?.User?.FindFirstValue("sub");            return Guid.TryParse(userIdClaim, out var userId) ? userId : null;        }    }    /// <inheritdoc />    public Guid? OrganizationId    {        get        {            // Issued by the Identity module via ScopedClaimsPrincipalFactory from            // the user's ACTIVE profile assignment (chat, 2026-10-05). Null for            // unauthenticated or Platform-level requests.            var orgClaim = _httpContextAccessor.HttpContext?.User?.FindFirstValue("organization_id");            return Guid.TryParse(orgClaim, out var orgId) ? orgId : null;        }    }    /// <inheritdoc />    public bool IsAuthenticated => _httpContextAccessor.HttpContext?.User?.Identity?.IsAuthenticated ?? false;}